using System;

class Greeter
{
    public string Name;
    public void Hello(string s) { Console.WriteLine(Name + " says " + s); }
}

class Program
{
    delegate void Say(string s);   // a delegate type = a method signature

    static void Shout(string s) { Console.WriteLine(s.ToUpper() + "!"); }

    static void Main()
    {
        Say d = Shout;                                   // static method
        d += new Greeter { Name = "Ann" }.Hello;         // instance method: target object is kept too
        d += s => Console.WriteLine("lambda: " + s);     // lambda, no class needed
        Console.WriteLine("Targets: " + d.GetInvocationList().Length);
        d("hi");                                         // multicast: all run in order
        d -= Shout;                                      // remove one subscriber
        Console.WriteLine("After removing Shout: " + d.GetInvocationList().Length);
        d("again");
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // custom delegate: needed because Func/Action cannot have ref parameters
    delegate void Doubler(ref int x);

    static void Main()
    {
        Func<int, int, int> add = (a, b) => a + b;     // returns a value
        Action<string> print = Console.WriteLine;      // returns void
        Predicate<int> isEven = n => n % 2 == 0;       // int -> bool

        var list = new List<int> { 1, 2, 3, 4, 5, 6 };
        print("input: " + string.Join(",", list));
        print("add(2,3) = " + add(2, 3));
        print("evens = " + string.Join(",", list.FindAll(isEven)));

        Doubler dbl = (ref int x) => { x *= 2; };
        int v = 21;
        dbl(ref v);
        print("ref doubled: " + v);
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Run(string name, List<Action> actions)
    {
        Console.Write(name + ": ");
        foreach (var a in actions) a();
        Console.WriteLine();
    }

    static void Main()
    {
        var bad = new List<Action>();
        for (int i = 0; i < 3; i++)
            bad.Add(() => Console.Write(i + " "));      // all share ONE i (captured by reference)

        var good = new List<Action>();
        for (int i = 0; i < 3; i++)
        {
            int copy = i;                               // new variable each iteration
            good.Add(() => Console.Write(copy + " "));
        }

        var each = new List<Action>();
        foreach (var n in new[] { 0, 1, 2 })            // foreach makes a fresh variable per pass
            each.Add(() => Console.Write(n + " "));

        Run("for loop (bug)", bad);     // 3 3 3
        Run("copy inside body", good);  // 0 1 2
        Run("foreach", each);           // 0 1 2
    }
}

using System;

class Button
{
    public event EventHandler Clicked;   // outside code can only += and -=
    public Action Raw;                   // public delegate field: anyone can do anything

    public void Click()
    {
        var handler = Clicked;           // copy once, then check and call
        if (handler != null) handler(this, EventArgs.Empty);
        if (Raw != null) Raw();
    }
}

class Program
{
    static void Main()
    {
        var b = new Button();
        b.Clicked += (s, e) => Console.WriteLine("event handler A");
        b.Clicked += (s, e) => Console.WriteLine("event handler B");
        // b.Clicked = null;   // compile error: event cannot be assigned from outside
        // b.Clicked(b, null); // compile error: event cannot be invoked from outside

        b.Raw += () => Console.WriteLine("raw handler A");
        b.Raw = () => Console.WriteLine("raw handler B");   // silently wipes A!
        b.Raw();                                            // outsiders could even call it directly

        Console.WriteLine("--- click ---");
        b.Click();   // A and B from the event, only B from the field
    }
}

using System;

class Publisher
{
    public static event Action Tick;     // long-lived publisher
    public static void Raise() { if (Tick != null) Tick(); }
    public static int Count() { return Tick == null ? 0 : Tick.GetInvocationList().Length; }
}

class View : IDisposable
{
    public string Name;
    public View(string name) { Name = name; Publisher.Tick += OnTick; }   // subscribe
    void OnTick() { Console.WriteLine("  " + Name + " handled tick"); }
    public void Dispose() { Publisher.Tick -= OnTick; }                   // unsubscribe
}

class Program
{
    static void Main()
    {
        var a = new View("viewA");
        var b = new View("viewB");
        Console.WriteLine("subscribers: " + Publisher.Count());
        a = null; b = null;                  // we 'forget' both views...
        Console.WriteLine("both references dropped, raising:");
        Publisher.Raise();                   // ...but the publisher still calls them: leaked

        var c = new View("viewC");
        c.Dispose();                         // proper cleanup
        Console.WriteLine("subscribers after viewC created and disposed: " + Publisher.Count());  // still 2 (A, B)
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        var list = new List<int> { 1, 2, 3 };
        Console.WriteLine("source: " + string.Join(",", list));

        var q = list.Where(x =>
        {
            Console.WriteLine("  checking " + x);   // shows when work really happens
            return x > 1;
        });
        Console.WriteLine("query built, nothing checked yet");

        list.Add(4);                                // query will see this: it runs later
        Console.WriteLine("count = " + q.Count());  // first enumeration
        Console.WriteLine("count again = " + q.Count()); // runs all checks AGAIN

        var snapshot = q.ToList();                  // materialise once
        list.Add(5);
        Console.WriteLine("snapshot = " + string.Join(",", snapshot));
        Console.WriteLine("snapshot count = " + snapshot.Count + " (no more checks)");
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static IEnumerable<int> Numbers()
    {
        Console.WriteLine("  body starts");       // not run until the first MoveNext
        try
        {
            for (int i = 1; i <= 5; i++)
            {
                Console.WriteLine("  yielding " + i);
                yield return i;                  // pause here, state is remembered
            }
        }
        finally
        {
            Console.WriteLine("  finally runs (Dispose)");
        }
    }

    static void Main()
    {
        Console.WriteLine("calling Numbers()");
        var seq = Numbers();                     // nothing printed from the body yet
        Console.WriteLine("got the sequence, starting foreach");
        foreach (var n in seq)
        {
            Console.WriteLine("main got " + n);
            if (n == 2) break;                   // break calls Dispose -> finally runs
        }
        Console.WriteLine("done");
    }
}

using System;
using System.Linq;

class Program
{
    static void Main()
    {
        var customers = new[] { new { Id = 1, Name = "Ann" }, new { Id = 2, Name = "Bob" } };
        var orders = new[] { new { CustId = 1, Total = 50 }, new { CustId = 1, Total = 70 }, new { CustId = 2, Total = 20 } };

        // query syntax
        var q1 = from c in customers
                 join o in orders on c.Id equals o.CustId
                 let big = o.Total > 40
                 where big
                 orderby o.Total descending
                 select c.Name + ":" + o.Total;

        // method syntax: what the compiler turns the query into
        var q2 = customers
            .Join(orders, c => c.Id, o => o.CustId, (c, o) => new { c, o })
            .Select(x => new { x, big = x.o.Total > 40 })      // 'let' = Select into anonymous type
            .Where(y => y.big)
            .OrderByDescending(y => y.x.o.Total)
            .Select(y => y.x.c.Name + ":" + y.x.o.Total);

        Console.WriteLine("query syntax:  " + string.Join(", ", q1));
        Console.WriteLine("method syntax: " + string.Join(", ", q2));
        Console.WriteLine("same result: " + q1.SequenceEqual(q2));
    }
}

using System;
using System.Linq;

class Program
{
    static void Main()
    {
        int n = 1000;
        int[] data = Enumerable.Range(1, n).ToArray();
        Console.WriteLine("input: 1.." + n + ", sum of squares of even numbers");

        // LINQ: every element goes through delegate calls for Where and Select
        int calls = 0;
        long linq = data.Where(x => { calls++; return x % 2 == 0; })
                        .Select(x => { calls++; return (long)x * x; })
                        .Sum();

        // plain loop: no delegates, no iterator objects
        long loop = 0;
        for (int i = 0; i < data.Length; i++)
        {
            int x = data[i];
            if (x % 2 == 0) loop += (long)x * x;
        }

        Console.WriteLine("LINQ result: " + linq + ", lambda calls: " + calls);  // n + n/2
        Console.WriteLine("loop result: " + loop + ", lambda calls: 0");
        Console.WriteLine("same answer: " + (linq == loop));
        // For ordinary code this overhead is tiny; measure before rewriting.
    }
}

using System;
using System.Linq;

class Program
{
    static void Main()
    {
        var people = new[] { new { Id = 1, Name = "Ann" }, new { Id = 2, Name = "Bob" }, new { Id = 3, Name = "Cy" } };
        var pets = new[] { new { OwnerId = 1, Pet = "Rex" }, new { OwnerId = 1, Pet = "Tom" }, new { OwnerId = 3, Pet = "Kit" } };

        Console.WriteLine("Inner join (Bob dropped):");
        foreach (var r in people.Join(pets, p => p.Id, t => t.OwnerId, (p, t) => p.Name + "-" + t.Pet))
            Console.WriteLine("  " + r);

        Console.WriteLine("Left outer join (GroupJoin + DefaultIfEmpty):");
        var left = people
            .GroupJoin(pets, p => p.Id, t => t.OwnerId, (p, g) => new { p, g })   // one row per person
            .SelectMany(x => x.g.DefaultIfEmpty(), (x, t) => new { x.p.Name, Pet = t == null ? "(none)" : t.Pet });
        foreach (var r in left)
            Console.WriteLine("  " + r.Name + "-" + r.Pet);
    }
}

using System;
using System.Linq.Expressions;

class Program
{
    static void Main()
    {
        // As a delegate: compiled code, opaque, can only be run
        Func<int, bool> del = x => x > 5;

        // As an expression tree: data describing the code, a provider can inspect it
        Expression<Func<int, bool>> expr = x => x > 5;

        Console.WriteLine("delegate result: " + del(7));
        Console.WriteLine("expression text: " + expr);
        Console.WriteLine("body node type : " + expr.Body.NodeType);
        var body = (BinaryExpression)expr.Body;
        Console.WriteLine("left  = " + body.Left + ", right = " + body.Right);

        // A provider such as EF Core walks this tree and writes e.g. "WHERE x > 5".
        // We can also still run it by compiling it:
        Console.WriteLine("compiled result: " + expr.Compile()(7));
    }
}

using System;
using System.Collections.Generic;

class EventAggregator
{
    private readonly Dictionary<Type, List<Delegate>> _map = new Dictionary<Type, List<Delegate>>();
    private readonly object _lock = new object();

    private class Token : IDisposable
    {
        public Action OnDispose;
        public void Dispose() { OnDispose(); }
    }

    public IDisposable Subscribe<T>(Action<T> handler)
    {
        lock (_lock)
        {
            List<Delegate> list;
            if (!_map.TryGetValue(typeof(T), out list)) _map[typeof(T)] = list = new List<Delegate>();
            list.Add(handler);
        }
        return new Token { OnDispose = () => { lock (_lock) { _map[typeof(T)].Remove(handler); } } };
    }

    public void Publish<T>(T message)
    {
        Delegate[] copy;
        lock (_lock)                                    // copy under the lock...
        {
            List<Delegate> list;
            copy = _map.TryGetValue(typeof(T), out list) ? list.ToArray() : new Delegate[0];
        }
        foreach (Action<T> h in copy)                   // ...invoke outside it
        {
            try { h(message); } catch (Exception e) { Console.WriteLine("handler failed: " + e.Message); }
        }
    }
}

class Program
{
    static void Main()
    {
        var bus = new EventAggregator();
        var t1 = bus.Subscribe<string>(m => Console.WriteLine("A got: " + m));
        var t2 = bus.Subscribe<string>(m => { throw new Exception("boom"); });
        bus.Subscribe<int>(n => Console.WriteLine("int handler got: " + n));
        bus.Publish("hello");
        bus.Publish(42);
        t1.Dispose();
        Console.WriteLine("after A unsubscribed:");
        bus.Publish("again");
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static int roundTrips = 0;

    // pretend database query: every enumeration is one round trip
    static IEnumerable<int> Query()
    {
        roundTrips++;
        for (int i = 1; i <= 5; i++) yield return i;
    }

    static void Main()
    {
        var q = Query().Where(x => x > 1);              // deferred, nothing ran yet
        Console.WriteLine("built, round trips = " + roundTrips);

        // refactor "made it LINQ-y": three uses = three enumerations
        bool any = q.Any();
        int count = q.Count();
        int sum = q.Sum();
        Console.WriteLine("any=" + any + " count=" + count + " sum=" + sum);
        Console.WriteLine("round trips (deferred, reused) = " + roundTrips);   // 3

        roundTrips = 0;
        var rows = Query().Where(x => x > 1).ToList();  // materialise once
        Console.WriteLine("any=" + rows.Any() + " count=" + rows.Count + " sum=" + rows.Sum());
        Console.WriteLine("round trips (ToList once) = " + roundTrips);         // 1
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        var list = new List<int> { 1, 2, 3 };
        var q = list.Select(x => x * 10);      // deferred: nothing computed here
        list.Add(4);                           // changes the source before enumeration
        Console.WriteLine("list = " + string.Join(",", list));
        Console.WriteLine("q.Sum() = " + q.Sum());          // 100

        var list2 = new List<int> { 1, 2, 3 };
        var snap = list2.Select(x => x * 10).ToList();      // snapshot taken now
        list2.Add(4);
        Console.WriteLine("snapshot sum = " + snap.Sum());  // 60

        var arr = new[] { 1, 2, 3 };
        var qa = arr.Select(x => x * 10);
        arr[0] = 7;                                         // replacing an element is allowed
        Console.WriteLine("array query sum = " + qa.Sum()); // 120
    }
}
